package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.OTPController; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import java.awt.*; public class OTPFrame extends BaseFrame {private static OTPController c;private static String email; static void setController(OTPController x){c=x;}static OTPController controller(){return c;}static void setEmail(String x){email=x;}public OTPFrame(){super("Verify OTP");JTextField o=new JTextField();JButton b=button("Verify");setLayout(new GridLayout(3,1));add(new JLabel("Six digit OTP:"));add(o);add(b);b.addActionListener(x->{if(c.verify(o.getText())){dispose();new ResetPasswordFrame(email,c).setVisible(true);}else DialogUtil.error(this,"Invalid or expired OTP.");});}}
